CREATE FUNCTION agri.strategy_selection_receipt_checksum(p_selection_receipt_id uuid) RETURNS character varying
    LANGUAGE sql STABLE
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, MDY'
    SET "IntervalStyle" TO 'postgres'
    SET extra_float_digits TO '1'
    AS $$
        SELECT encode(
            digest(
                concat_ws(
                    '|',
                    'strategy_selection_receipt_v1',
                    receipt.selection_key,
                    receipt.analysis_subject_id::text,
                    coalesce(receipt.forecast_receipt_id::text, ''),
                    coalesce(receipt.forecast_iteration_id::text, ''),
                    receipt.feature_snapshot_id::text,
                    receipt.training_run_id::text,
                    receipt.selection_policy_id::text,
                    receipt.issue_time::text,
                    receipt.applicability_start::text,
                    receipt.applicability_end::text,
                    receipt.data_cutoff::text,
                    receipt.execution_mode,
                    receipt.claim_tier,
                    receipt.decision_state,
                    coalesce(receipt.abstention_reason, ''),
                    receipt.candidate_count::text,
                    feature.feature_checksum,
                    training.validation_checksum,
                    training.model_checksum,
                    training.strategy_label_checksum,
                    label.receipt_checksum,
                    policy.policy_checksum,
                    coalesce(forecast.receipt_checksum, ''),
                    coalesce(iteration.receipt_checksum, ''),
                    coalesce(
                        string_agg(
                            candidate.candidate_checksum,
                            '|' ORDER BY candidate.rank NULLS LAST, candidate.strategy_id
                        ),
                        ''
                    )
                ),
                'sha256'
            ),
            'hex'
        )::varchar
        FROM agri.strategy_selection_receipt AS receipt
        INNER JOIN agri.forecast_feature_snapshot AS feature
            ON feature.id = receipt.feature_snapshot_id
        INNER JOIN agri.forecast_training_run AS training
            ON training.id = receipt.training_run_id
        INNER JOIN agri.strategy_label_release AS label
            ON label.id = training.strategy_label_release_id
        INNER JOIN agri.strategy_selection_policy AS policy
            ON policy.id = receipt.selection_policy_id
        LEFT JOIN agri.forecast_receipt AS forecast
            ON forecast.id = receipt.forecast_receipt_id
        LEFT JOIN agri.forecast_iteration AS iteration
            ON iteration.id = receipt.forecast_iteration_id
        LEFT JOIN agri.strategy_selection_candidate AS candidate
            ON candidate.selection_receipt_id = receipt.id
        WHERE receipt.id = p_selection_receipt_id
        GROUP BY
            receipt.id,
            feature.feature_checksum,
            training.validation_checksum,
            training.model_checksum,
            training.strategy_label_checksum,
            label.receipt_checksum,
            policy.policy_checksum,
            forecast.receipt_checksum,
            iteration.receipt_checksum
    $$;
